package Tv6.Controller;
import Tv6.View.ChuongTrinhPage;
import MainPage.View.Workspace;import MainPage.Controller.PageTasks;import Model.DanhMucModel;import Service.DanhMucService;import java.util.*;import java.time.LocalDate;import java.math.BigDecimal;import javax.swing.*;
public class ChuongTrinhController {
 private final ChuongTrinhPage v;private final int b;private final DanhMucService svc=new DanhMucService();private List<DanhMucModel> data=List.of();private final JCheckBox only;
 public ChuongTrinhController(ChuongTrinhPage v,int b){this(v,b,"Cơ sở #"+b);}
 public ChuongTrinhController(ChuongTrinhPage v,int b,String name){this.v=v;this.b=b;v.title("CHƯƠNG TRÌNH — "+name,"Danh mục của cơ sở");v.columns("Mã","Ký hiệu","Tên","Mô tả","Từ ngày","Đến ngày","Đang hiệu lực");only=v.checkFilter("Chỉ đang kích hoạt",this::render);v.action("+ Thêm",()->edit(null));v.action("Sửa",()->{var x=selected();if(x!=null)edit(x);});v.action("Ngừng kích hoạt",()->{var x=selected();if(x!=null&&Workspace.confirm(v,"Ngừng kích hoạt "+x.getTenDanhMuc()+"?"))PageTasks.run(v,()->{x.setTrangThai(false);PageTasks.require(svc.update(b,x),"Không lưu được");return true;},r->load(false));});v.action("Tải lại",()->load(true));load(false);}
 private String field(DanhMucModel x,String k){return PageTasks.field(x==null?null:x.getCauHinh(),k);}
 private boolean active(DanhMucModel x){if(!x.isTrangThai())return false;try{LocalDate now=LocalDate.now();return !now.isBefore(LocalDate.parse(field(x,"TuNgay")))&&!now.isAfter(LocalDate.parse(field(x,"DenNgay")));}catch(Exception e){return false;}}
 private void load(boolean force){v.status("Đang tải...");PageTasks.run(v,()->(force?svc.reload(b):svc.selectAll(b)).stream().filter(x->"CHUONG_TRINH".equals(x.getNhomDanhMuc())).toList(),r->{data=r;render();});}
 private void render(){v.rows(data.stream().filter(x->!only.isSelected()||active(x)).map(x->new Object[]{x.getMaDanhMuc(),x.getMaKyHieu(),x.getTenDanhMuc(),field(x,"MoTa"),field(x,"TuNgay"),field(x,"DenNgay"),active(x)}).toArray(Object[][]::new));v.status("Tổng: "+data.size());}
 private DanhMucModel selected(){int r=v.selected();if(r<0){Workspace.message(v,"Chọn dòng trước");return null;}int id=(int)v.value(r,0);return data.stream().filter(x->x.getMaDanhMuc()==id).findFirst().orElse(null);}
 private void edit(DanhMucModel x){try{Workspace.Form form=new Workspace.Form(Workspace.Field.text("Ký hiệu",x==null?"":x.getMaKyHieu()),Workspace.Field.text("Tên",x==null?"":x.getTenDanhMuc()),Workspace.Field.text("Mô tả",field(x,"MoTa")),Workspace.Field.text("Từ ngày (yyyy-MM-dd)",field(x,"TuNgay")),Workspace.Field.text("Đến ngày",field(x,"DenNgay")),Workspace.Field.check("Kích hoạt",x==null||x.isTrangThai()));if(form.show(v,"Chương trình","Lưu","Hủy")!=0)return;LocalDate a=LocalDate.parse(form.text(3).trim()),z=LocalDate.parse(form.text(4).trim());PageTasks.require(!z.isBefore(a),"Ngày kết thúc trước ngày bắt đầu");String config=PageTasks.mergeFields(x==null?null:x.getCauHinh(),Map.of("MoTa",PageTasks.jsonString(form.text(2)),"TuNgay",PageTasks.jsonString(a.toString()),"DenNgay",PageTasks.jsonString(z.toString())));boolean on=form.checked(5);String key=form.text(0).trim(),label=form.text(1).trim();PageTasks.run(v,()->{DanhMucModel m=x==null?new DanhMucModel():x;m.setNhomDanhMuc("CHUONG_TRINH");m.setMaKyHieu(key);m.setTenDanhMuc(label);m.setCauHinh(config);m.setTrangThai(on);PageTasks.require(x==null?svc.insert(b,m):svc.update(b,m),"Không lưu được danh mục");return true;},r->load(false));}catch(Exception e){Workspace.message(v,"WARNING — "+e.getMessage());}}
}
